// DETERMINISTIC: fetched HTML -> clean plain text (no AI)
let html = $json.data ?? $json.body ?? $json;
if (typeof html !== 'string') html = JSON.stringify(html);
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#\d+;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const title = $('Submit Article').first().json['Article Title'] || 'Untitled';
return [{ json: { content: text, title } }];

// DETERMINISTIC validation + FALLBACK. No truncation here - the Chunk node handles length.
const item = $input.first().json;
let text = (item.content || '').toString().trim();
let title = (item.title || 'Untitled').toString().trim();
if (text.length < 200) {
  throw new Error('FALLBACK: source text too short (' + text.length + ' chars). Provide a URL that returns readable article text, or paste at least ~200 characters.');
}
const HARD_CAP = 60000; // safety ceiling; long docs are chunked, not dropped
if (text.length > HARD_CAP) text = text.slice(0, HARD_CAP);
return [{ json: { title, source_text: text, char_count: text.length } }];

// DETERMINISTIC: split the source into overlapping chunks -> one item per chunk (the MAP fan-out).
const { title, source_text } = $input.first().json;
const CHUNK = 4000, OVERLAP = 200;
const chunks = [];
let i = 0;
while (i < source_text.length) {
  const end = Math.min(i + CHUNK, source_text.length);
  chunks.push(source_text.slice(i, end));
  if (end >= source_text.length) break;
  i = end - OVERLAP;
}
const total = chunks.length || 1;
return (chunks.length ? chunks : ['']).map((c, idx) => ({
  json: { title, chunk_text: c, chunk_index: idx + 1, total_chunks: total }
}));

// DETERMINISTIC: lenient parse of one chunk's Summarizer output. Never throws - a bad chunk yields no claims.
let raw = $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = raw.toString().replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
}
const claims = parsed && Array.isArray(parsed.claims)
  ? parsed.claims.map(c => (typeof c === 'string' ? c : (c && c.claim) || '')).filter(Boolean)
  : [];
const chunk_summary = parsed && parsed.chunk_summary ? String(parsed.chunk_summary) : '';
return [{ json: { claims, chunk_summary } }];

// DETERMINISTIC REDUCE-prep: gather every chunk's output, dedup claims, concatenate partial summaries.
const all = $input.all().map(i => i.json);
const summaries = all.map(a => a.chunk_summary).filter(Boolean);
const seen = new Set(), dedup = [];
for (const a of all) {
  for (const c of (a.claims || [])) {
    const t = String(c).trim();
    const k = t.toLowerCase().replace(/\s+/g, ' ').slice(0, 120);
    if (t && !seen.has(k)) { seen.add(k); dedup.push(t); }
  }
}
const title = $('Validate & Prepare Input').first().json.title;
return [{ json: {
  title,
  combined_text: summaries.join('\n'),
  candidate_claims: dedup,
  total_chunks: all.length
} }];

