// DETERMINISTIC parse + validate of the Synthesizer JSON, with a bounded self-correction signal.
// $runIndex is 0 on the first pass and 1 after one retry -> we allow exactly one retry.
let raw = $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = raw.toString().replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
}
const ok = !!(parsed && Array.isArray(parsed.key_claims) && parsed.key_claims.length > 0);
const attempt = $runIndex;
const needs_retry = !ok && attempt < 1;
const merge = $('Merge Chunk Summaries').first().json;

let summary_obj;
if (ok) {
  const claims = parsed.key_claims
    .map((c, i) => ({ id: c.id ?? (i + 1), claim: String((c && c.claim) || c || '').trim() }))
    .filter(c => c.claim);
  summary_obj = { title: parsed.title || merge.title, summary: String(parsed.summary || ''), key_claims: claims };
} else {
  // FALLBACK after the retry budget is spent: build claims deterministically from candidates.
  const cc = (merge.candidate_claims || []).slice(0, 8).map((c, i) => ({ id: i + 1, claim: c }));
  summary_obj = { title: merge.title, summary: (merge.combined_text || '').slice(0, 600), key_claims: cc };
}
return [{ json: {
  summary_obj, needs_retry, attempt,
  title: merge.title, combined_text: merge.combined_text, candidate_claims: merge.candidate_claims
} }];

// DEMO AFFORDANCE (deterministic, not model output): append the optional injected claim so the
// Verifier has a guaranteed not-in-source claim to catch, driving the human-review branch reproducibly.
const summary_obj = $json.summary_obj;
const inject = ($('Submit Article').first().json['Inject Test Claim'] || '').toString().trim();
if (inject) {
  const nextId = Math.max(0, ...summary_obj.key_claims.map(c => c.id)) + 1;
  summary_obj.key_claims.push({ id: nextId, claim: inject });
}
const source_text = $('Validate & Prepare Input').first().json.source_text;
return [{ json: { summary_obj, source_text, title: summary_obj.title } }];

// DETERMINISTIC scoring + 3-tier routing policy (no AI). Confidence-weighted, with a hard unsupported gate.
let raw = $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw === 'object') raw = JSON.stringify(raw);
raw = raw.toString().replace(/```json/gi, '').replace(/```/g, '').trim();
let v = null;
try { v = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { v = JSON.parse(m[0]); } catch (e2) {} }
}
const summary = $('Inject Test Claim').first().json.summary_obj;
const title = $('Inject Test Claim').first().json.title;

// FALLBACK: unusable verifier output -> mark everything UNSUPPORTED -> forces the safe (review) path.
if (!v || !Array.isArray(v.verifications) || v.verifications.length === 0) {
  v = { verifications: (summary.key_claims || []).map(c => ({ id: c.id, claim: c.claim, verdict: 'UNSUPPORTED', evidence: '', confidence: 0 })) };
}

const total = v.verifications.length || 1;
const supported = v.verifications.filter(x => x.verdict === 'SUPPORTED').length;
const partial = v.verifications.filter(x => x.verdict === 'PARTIAL').length;
const unsupported = v.verifications.filter(x => x.verdict === 'UNSUPPORTED').length;

const trust_score = Math.round((supported / total) * 100);
let wsum = 0;
for (const x of v.verifications) {
  const c = Math.max(0, Math.min(1, Number(x.confidence) || 0));
  if (x.verdict === 'SUPPORTED') wsum += c;
  else if (x.verdict === 'PARTIAL') wsum += 0.5 * c;
}
const weighted_score = Math.round((wsum / total) * 100);
const low_conf = v.verifications.some(x => x.verdict === 'SUPPORTED' && (Number(x.confidence) || 0) < 0.5);

// POLICY (lives in code, not in a prompt, so it can't drift run-to-run):
let route, needs_review;
if (unsupported > 0 || weighted_score < 70) { route = 'HARD_REVIEW'; needs_review = true; }
else if (trust_score < 90 || partial > 0 || low_conf) { route = 'LIGHT_REVIEW'; needs_review = false; }
else { route = 'AUTO_PUBLISH'; needs_review = false; }

return [{ json: {
  title, summary, verifications: v.verifications,
  stats: { total, supported, partial, unsupported, trust_score, weighted_score, low_conf, n_chunks: $('Merge Chunk Summaries').first().json.total_chunks },
  route, needs_review,
  reviewer_email: $('Submit Article').first().json['Reviewer Email'] || ''
} }];

// DETERMINISTIC: turn the human reviewer's click into a status.
const approved = $json.data && $json.data.approved === true;
const p = $('Score & Decide Route').first().json;
return [{ json: {
  ...p,
  status: approved ? 'APPROVED_BY_REVIEWER' : 'NEEDS_REVISION',
  reviewer_note: approved ? 'Human reviewer approved publication.' : 'Human reviewer flagged this for revision.'
} }];
